/* every entry of one group, roots first then each subtree in reading order
   -- the shape the group page's collapsible list and the depth control
   both work from */
function groupNodes(gi) {
  var nodes = [];
  function collect(i, depth) {
    nodes.push({ i: i, d: depth });
    for (var c = firstM[i]; c >= 0; c = nextM[c]) collect(c, depth + 1);
  }
  grpMembers(gi).forEach(function (i) { collect(i, 0); });
  return nodes;
}

/* ---- the group page: the entries under one upright-bold heading ---- */
