  if (t.slice(0, k.length) !== k) return t;
  var i = k.length;
  while (i < t.length && /\s/.test(t[i])) i++;
  if (t[i] !== '=' && t[i] !== '\u2013' && t[i] !== '\u2014') return t;
  i++;
