  if (id[0] === 'c') { var ci = CHI[id.slice(1)]; if (ci !== undefined) { state.selCh = ci; state.selDiv = -1; state.selGrp = -1; state.sel = -1; renderPane(); } }
  if (id[0] === 'd') { state.selDiv = parseInt(id.slice(1), 10); state.selCh = -1; state.selGrp = -1; state.sel = -1; renderPane(); }
  if (id[0] === 'g') {
    var gi = parseInt(id.slice(1), 10);
    /* expanding a group also opens its page, the way a division does */
    if (gi >= 0 && gi < NG && state.expanded[id]) {
      state.selGrp = gi; state.selDiv = -1; state.selCh = -1; state.sel = -1;
      renderPane();
    }
  }
