function routeFromHash() {
  var p = hashParams();
  var v = p.v || 'browse';
  var q = p.q || '', m = p.m || '', c = p.c || '', k = p.k || '';
  var d = p.d === undefined ? -1 : parseInt(p.d, 10);
  if (isNaN(d)) d = -1;
  var adv = p.adv === '1';
  if (adv !== state.adv) { state.adv = adv; syncQMode(); }
  if (q !== state.q) { setQuery(q); applyQuery(q, true); }
  if (v !== state.view) setView(v);
  if (v === 'refs') {
    if (k) { state.refKey = k; renderSourceDetail(k); }
    updateURLState(false);
    return;
  }
  if (v === 'atu') {
    var tn = p.t === undefined ? -1 : parseInt(p.t, 10);
    if (isNaN(tn)) tn = -1;
    state.atuSel = (tn >= 0 && atuByNum.has(tn)) ? atuByNum.get(tn) : -1;
    updateURLState(false);
    renderATU();
    return;
  }
  state.atuSel = -1;   /* leaving the type index drops its selection */
  if (m && byNum.has(m)) {
    var i = byNum.get(m);
    state.sel = i; state.selDiv = -1; state.selGrp = -1; state.selCh = -1;
    if (!state.q) reveal(i);
    flatten(); renderList(true); renderPane(); scrollToSel();
  } else if (d >= 0 && d < ND) {
    state.selDiv = d; state.selCh = -1; state.selGrp = -1; state.sel = -1;
    state.expanded['d' + d] = 1;
    flatten(); renderList(true); renderPane();
  } else if (p.g !== undefined) {
    var gi = parseInt(p.g, 10);
    if (isNaN(gi) || gi < 0 || gi >= NG) gi = -1;
    if (gi >= 0) { selectGroup(gi, false); return; }
    state.sel = -1; state.selDiv = -1; state.selGrp = -1; state.selCh = -1;
    flatten(); renderList(true); renderPane();
  } else if (c && CHI[c] !== undefined) {
    state.selCh = CHI[c]; state.selDiv = -1; state.selGrp = -1; state.sel = -1;
    state.expanded['c' + c] = 1;
    flatten(); renderList(true); renderPane();
  } else if (state.sel >= 0 || state.selDiv >= 0 || state.selGrp >= 0 || state.selCh >= 0) {
    /* The URL carries no motif / division / group / chapter, so the selection is
       gone.  Without this the stale selection would be written straight back
       into the URL, which undoes the very navigation that brought us here --
       going Forward to a bare "#q=a" used to land on "#q=a&m=A1.2" again. */
    if (state.q) applyQuery(state.q, true);
    else { state.sel = -1; state.selDiv = -1; state.selGrp = -1; state.selCh = -1; renderPane(); }
  }
  updateURLState(false);
}

